const payload = $input.first().json;
const config = $('Configure digest').first().json;

if (!payload?.success || !Array.isArray(payload?.data?.items)) {
  throw new Error('MemoTune returned an unexpected response.');
}

const escapeSlack = (value) =>
  String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');

const minimumPlayCount = Math.max(0, Number(config.minimumPlayCount) || 0);
const maximumSongs = Math.min(10, Math.max(1, Number(config.maximumSongs) || 5));
const songs = payload.data.items
  .filter((song) => song?.sourceCode && Number(song.playCount ?? 0) >= minimumPlayCount)
  .slice(0, maximumSongs);

const heading = `*${escapeSlack(config.digestTitle || 'Daily MemoTune AI song digest')}*`;

if (songs.length === 0) {
  return [{
    json: {
      generatedAt: new Date().toISOString(),
      songCount: 0,
      text: `${heading}\nNo songs matched the current filters.`,
    },
  }];
}

const lines = songs.map((song, index) => {
  const songUrl = `https://memotune.com/song/${encodeURIComponent(song.sourceCode)}`;
  const title = escapeSlack(song.title || 'Untitled song');
  const author = escapeSlack(song.author?.name || 'MemoTune creator');
  const plays = Number(song.playCount ?? 0);
  const likes = Number(song.likeCount ?? 0);
  const tags = Array.isArray(song.styleTags)
    ? song.styleTags.slice(0, 3).map((tag) => `#${escapeSlack(tag)}`).join(' ')
    : '';

  return `${index + 1}. *<${songUrl}|${title}>* — ${author}\n   ${plays} plays · ${likes} likes${tags ? ` · ${tags}` : ''}`;
});

return [{
  json: {
    generatedAt: new Date().toISOString(),
    songCount: songs.length,
    text: [
      heading,
      ...lines,
      '<https://memotune.com/community|Browse the MemoTune community>',
    ].join('\n\n'),
  },
}];
